```ts
import type { GeospatialCamera } from "@babylonjs/lite";

export function centerOnLatLon(camera: GeospatialCamera, latitudeDeg: number, longitudeDeg: number): void {
    const R = camera.limits.planetRadius;
    const lat = (latitudeDeg * Math.PI) / 180;
    const lon = (longitudeDeg * Math.PI) / 180;

    camera.center = {
        x: R * Math.cos(lat) * Math.cos(lon),
        y: -R * Math.cos(lat) * Math.sin(lon),
        z: R * Math.sin(lat),
    };
}
```

I wrote `src/center-on.ts` which converts the latitude/longitude to a point on the planet sphere (north = +Z, east = −Y at the prime meridian, per note 58) and assigns a new object to `camera.center` so the camera re-orbits immediately while preserving yaw, pitch, and radius (per note 13). I was not unsure of anything — the coordinate convention is fully pinned down by the notes.
